// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { AbsoluteFill, useCurrentFrame, useVideoConfig, spring, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadPlayfair = makeLoadFont('PlayfairDisplay');
const loadInter = makeLoadFont('Inter');

// Load fonts at module level to ensure they are ready before render
const { fontFamily: playfairFamily } = loadPlayfair();
const { fontFamily: interFamily } = loadInter();



export type CinematicLowerThirdProps = Record<string, any>;

const CinematicLowerThird: React.FC<CinematicLowerThirdProps> = ({
  backgroundColor = "#000000",
  transparentBackground = true,
  durationInSeconds = 6,
  name = "Michelle Lopilato",
  title = "Real Estate Agent | Lopilato Living",
  accentColor = "#D4AF37", // Cinematic gold accent
  nameColor = "#FFFFFF",
  titleColor = "#CCCCCC",
  scale = 1.0,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Prevent parser errors by evaluating transparency logic
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Timing calculations
  const durationFrames = durationInSeconds * fps;
  const outroStartFrame = Math.max(0, durationFrames - fps * 1.5); // 1.5 seconds for a smooth outro

  // Animation Springs
  const introSpring = spring({
    fps,
    frame,
    config: {
      damping: 14,
      stiffness: 90,
      mass: 0.8,
    },
  });

  const outroSpring = spring({
    fps,
    frame: frame - outroStartFrame,
    config: {
      damping: 14,
      stiffness: 90,
      mass: 0.8,
    },
  });

  // Responsive Layout Variables
  const safeLeft = width * 0.08;
  const safeBottom = height * 0.12;
  const baseNameSize = height * 0.07 * scale;
  const baseTitleSize = height * 0.025 * scale;
  const gapSpacing = height * 0.01 * scale;
  const lineThickness = Math.max(2, height * 0.003 * scale);

  // Derived Animation Values
  // Combine intro (0 -> 1) and outro (0 -> 1) into a single progress variable where appropriate
  const overallOpacity = interpolate(introSpring, [0, 0.5], [0, 1], { extrapolateRight: "clamp" }) - 
                         interpolate(outroSpring, [0, 0.5], [0, 1], { extrapolateRight: "clamp" });

  const lineScaleX = Math.max(0, introSpring - outroSpring);

  // Name animates up from the baseline during intro, and down during outro
  const nameTranslateY = interpolate(introSpring, [0, 1], [baseNameSize * 1.5, 0]) + 
                         interpolate(outroSpring, [0, 1], [0, baseNameSize * 1.5]);

  // Title animates down from the baseline during intro, and up during outro
  const titleTranslateY = interpolate(introSpring, [0, 1], [-baseTitleSize * 2, 0]) + 
                          interpolate(outroSpring, [0, 1], [0, -baseTitleSize * 2]);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      {/* Lower Third Container */}
      <div
        style={{
          position: "absolute",
          left: safeLeft,
          bottom: safeBottom,
          display: "flex",
          flexDirection: "column",
          alignItems: "flex-start",
          justifyContent: "center",
          gap: gapSpacing,
          transition: "none",
        }}
      >
        {/* Name Wrapper (Overflow hidden for the cinematic mask reveal) */}
        <div style={{ overflow: "hidden", paddingBottom: "2px", transition: "none" }}>
          <div
            style={{
              fontFamily: playfairFamily,
              fontSize: `${baseNameSize}px`,
              color: nameColor,
              fontWeight: 600,
              lineHeight: 1,
              transform: `translateY(${nameTranslateY}px)`,
              opacity: overallOpacity,
              textShadow: "0px 4px 16px rgba(0,0,0,0.5)",
              letterSpacing: "0.02em",
              transition: "none",
            }}
          >
            {name}
          </div>
        </div>

        {/* Accent Divider Line */}
        <div
          style={{
            height: `${lineThickness}px`,
            backgroundColor: accentColor,
            width: "100%",
            transform: `scaleX(${lineScaleX})`,
            transformOrigin: "left center",
            opacity: Math.max(0, overallOpacity),
            boxShadow: `0px 0px 10px ${accentColor}60`,
            borderRadius: "2px",
            transition: "none",
          }}
        />

        {/* Title Wrapper (Overflow hidden for mask reveal) */}
        <div style={{ overflow: "hidden", paddingTop: "2px", transition: "none" }}>
          <div
            style={{
              fontFamily: interFamily,
              fontSize: `${baseTitleSize}px`,
              color: titleColor,
              fontWeight: 400,
              letterSpacing: "0.2em",
              textTransform: "uppercase",
              lineHeight: 1.2,
              transform: `translateY(${titleTranslateY}px)`,
              opacity: overallOpacity,
              textShadow: "0px 2px 8px rgba(0,0,0,0.6)",
              transition: "none",
            }}
          >
            {title}
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default CinematicLowerThird;